/**
 * Copies team-owned sources into the app (run locally: `npm run sync`). The copies are committed,
 * so the Render build (`npm run build`) does not need the rest of the site/ folder.
 * The generated JSON carries data only — no «generated by… do not edit» lines and none of the authors' notes: these files
 * are imported by the app and end up in the public build (RC-9, security review В-5; guarded by e2e/flows.spec.ts).
 *
 *   site/copy/messages.{ru,en}.json      → messages/{ru,en}.json   (single source of visible strings; keys must match)
 *   site/3d/models/*.glb (manifest)      → public/models/           (LOD0 + LOD1, hashed names)
 *   node_modules/three/…/libs/basis/*    → public/basis/            (KTX2 transcoder, same three version as the app)
 *   site/3d/posters/*.{webp,avif,png}    → public/posters/
 *   site/3d/zones.js                     → src/lib/body3d/zones-core.js (zone classifier; ids = README zone directory)
 *   site/design/body2d/svg/*.svg         → public/body2d/           (2D fallback, same zoneIds)
 *   site/design/brand-kit/fonts/Manrope-subset.woff2 → src/fonts/Manrope.woff2
 *   site/design/brand-kit/favicon/*      → public/ (favicons, site.webmanifest, site.ru.webmanifest)
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { createRequire } from 'node:module';
import { brandPlates } from './brand-plate.mjs';
import { lpWorkingConfig } from './lp-config-pick.mjs';

const APP = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const SITE = path.resolve(APP, '..');
const rel = (p) => path.relative(APP, p);
const copy = (from, to) => { fs.mkdirSync(path.dirname(to), { recursive: true }); fs.copyFileSync(from, to); console.log('  ', rel(from), '→', rel(to)); };

if (!fs.existsSync(path.join(SITE, 'copy', 'messages.ru.json'))) {
  console.log('sync-assets: team folders not found next to the app — using committed copies.');
  process.exit(0);
}

// 1) messages: identical key sets in RU and EN
const flat = (o, p = '', out = {}) => { for (const [k, v] of Object.entries(o)) { const q = p ? `${p}.${k}` : k; if (v && typeof v === 'object') flat(v, q, out); else out[q] = v; } return out; };
const ru = JSON.parse(fs.readFileSync(path.join(SITE, 'copy', 'messages.ru.json'), 'utf8'));
const en = JSON.parse(fs.readFileSync(path.join(SITE, 'copy', 'messages.en.json'), 'utf8'));
const kr = Object.keys(flat(ru)), ke = new Set(Object.keys(flat(en)));
const diff = kr.filter((k) => !ke.has(k)).concat([...ke].filter((k) => !kr.includes(k)));
if (diff.length) { console.error('messages: RU/EN keys differ:', diff.slice(0, 20)); process.exit(1); }
console.log('messages:', kr.length, 'keys (RU = EN)');
for (const l of ['ru', 'en']) copy(path.join(SITE, 'copy', `messages.${l}.json`), path.join(APP, 'messages', `${l}.json`));
// 1a) the ad landing's config (Market Analyst: versions, offer, form, notifications, tracking rules) — committed, because
// Render builds without site/ (same trap as messages, R-LP-03); the gate compares it with the deck
// RC-9 (security review В-5): only the WORKING fields — the deck file also carries the authors' notes, and this JSON is
// imported by client code, i.e. shipped whole to the browser (scripts/lp-config-pick.mjs)
fs.writeFileSync(path.join(APP, 'src', 'lib', 'lp', 'config.json'), `${JSON.stringify(lpWorkingConfig(JSON.parse(fs.readFileSync(path.join(SITE, 'copy', 'lp-config.json'), 'utf8'))), null, 1)}\n`);
console.log('   lp/config.json written (working fields of copy/lp-config.json)');
// 1a') the denylist of the deck (banned words; the landing's own list) for the gate — committed for the same reason: read
// from site/copy, the check was silently skipped wherever that folder is absent (RC-9, T-1; e2e/lp.spec.ts)
copy(path.join(SITE, 'copy', 'lexicon-denylist.json'), path.join(APP, 'e2e', 'fixtures', 'lexicon-denylist.json'));

// 1b) mock catalogue for the prototype BFF: copy/mock-data.json (Market Analyst, client's plan 650/750/900 AED) with titles and
// descriptions resolved from the deck per locale — the mock answers like Altegio (localized strings), and the client bundle
// does not need the whole dictionary. Missing keys fail the sync.
{
  const mock = JSON.parse(fs.readFileSync(path.join(SITE, 'copy', 'mock-data.json'), 'utf8'));
  const fr = flat(ru), fe = flat(en);
  const l10n = (key) => { if (fr[key] === undefined || fe[key] === undefined) { console.error('mock-data: missing message key', key); process.exit(1); } return { ru: fr[key], en: fe[key] }; };
  const catalog = {
    currency: mock.currency,
    categories: mock.categories.map((c) => ({ key: c.id, title: l10n(c.titleKey) })),
    services: mock.services.map((s) => ({
      key: s.id, categoryKey: s.categoryId, title: l10n(s.titleKey), description: l10n(s.descriptionKey),
      priceMin: s.priceMin, durationMin: s.durationMin, priceOnRequest: s.priceOnRequest, // no «confirm with the client» flag: a note, not data (В-5)
    })),
    specialist: l10n('placeholder.specialist'), // lead: specialists only «Специалист студии» / «Демо», no names
    articleTitle: l10n('mock.articles.title'), // «Демо-статья {n}»
    articleTodo: l10n('journal.todo.articles'),
    demo: l10n(mock.demoBadgeKey),
  };
  fs.writeFileSync(path.join(APP, 'src', 'lib', 'api', 'mock-catalog.json'), JSON.stringify(catalog, null, 1));
  console.log('   mock-catalog.json written:', catalog.services.length, 'services');
}

// 1c) Altegio comment (ТЗ §08, README п.10): bilingual RU + EN template (copy/comment-template.json, Market Analyst),
// zone names and sides from BOTH decks regardless of the site language. Extracted so the formatter stays small.
{
  const tpl = JSON.parse(fs.readFileSync(path.join(SITE, 'copy', 'comment-template.json'), 'utf8'));
  const data = {
    modes: tpl.modes, default: tpl.default, prefixes: tpl.prefixes, labels: tpl.labels, pairJoiner: tpl.bothFormat.pairJoiner,
    joiners: tpl.joiners, maxLength: tpl.maxLength, examples: tpl.examples, zones: { ru: ru.body3d.zones, en: en.body3d.zones } };
  fs.mkdirSync(path.join(APP, 'src', 'lib', 'altegio'), { recursive: true });
  fs.writeFileSync(path.join(APP, 'src', 'lib', 'altegio', 'comment-data.json'), JSON.stringify(data, null, 1));
  console.log('   altegio/comment-data.json written');
}

// 2) 3D models from the spike manifest (hashed names), transcoder, posters, zone classifier
const man = JSON.parse(fs.readFileSync(path.join(SITE, '3d', 'models', 'manifest.json'), 'utf8'));
fs.rmSync(path.join(APP, 'public', 'models'), { recursive: true, force: true });
const models = {};
for (const g of ['male', 'female']) {
  models[g] = {};
  for (const lod of ['lod0', 'lod1']) {
    const f = man.models[g][lod];
    copy(path.join(SITE, '3d', f), path.join(APP, 'public', 'models', path.basename(f)));
    models[g][lod] = '/models/' + path.basename(f);
    models[g][lod + 'Bytes'] = man.build[`${g}.${lod}`].bytes;
  }
}
// transcoder must match the app's three.js version (KTX2Loader ↔ basis_transcoder), so it comes from node_modules
for (const f of ['basis_transcoder.js', 'basis_transcoder.wasm']) copy(path.join(APP, 'node_modules', 'three', 'examples', 'jsm', 'libs', 'basis', f), path.join(APP, 'public', 'basis', f));
const posters = {};
for (const g of ['male', 'female']) {
  for (const e of ['avif', 'webp', 'png']) copy(path.join(SITE, '3d', 'posters', `hero-${g}@2x.${e}`), path.join(APP, 'public', 'posters', `hero-${g}@2x.${e}`));
  posters[g] = { avif: `/posters/hero-${g}@2x.avif`, webp: `/posters/hero-${g}@2x.webp`, png: `/posters/hero-${g}@2x.png`, width: 1350, height: 1800 };
}
fs.mkdirSync(path.join(APP, 'src', 'lib', 'body3d'), { recursive: true });
fs.writeFileSync(path.join(APP, 'src', 'lib', 'body3d', 'assets.json'), JSON.stringify({ models, posters, transcoderPath: '/basis/' }, null, 1));
console.log('   assets.json written');
copy(path.join(SITE, '3d', 'zones.js'), path.join(APP, 'src', 'lib', 'body3d', 'zones-core.js'));
// what the runtime needs from it (keys in _ZONE order, base zones, pairs) — without the classifier code (≈5 KB gzip off the
// first screen; the GLBs are baked, the browser never classifies)
{
  const core = createRequire(import.meta.url)(path.join(APP, 'src', 'lib', 'body3d', 'zones-core.js'));
  const meta = { keys: core.KEYS, keyIndex: core.KEY_INDEX, zones: core.ZONES.map((z) => ({ id: z.id, paired: !!z.paired })) };
  fs.writeFileSync(path.join(APP, 'src', 'lib', 'body3d', 'zones-meta.json'), JSON.stringify(meta, null, 1));
  console.log('   zones-meta.json written');
}

// 3) 2D silhouettes and font
for (const f of fs.readdirSync(path.join(SITE, 'design', 'body2d', 'svg')).filter((x) => x.endsWith('.svg'))) copy(path.join(SITE, 'design', 'body2d', 'svg', f), path.join(APP, 'public', 'body2d', f));
// which zones each view shows (from the same silhouettes): 3D anchors of zones without a front surface go to the back (M-01)
{
  const views = {};
  for (const f of fs.readdirSync(path.join(SITE, 'design', 'body2d', 'svg')).filter((x) => /^body-(male|female)-(front|back)\.svg$/.test(x))) {
    const [, g, v] = f.match(/^body-(male|female)-(front|back)\.svg$/);
    const ids = [...new Set([...fs.readFileSync(path.join(SITE, 'design', 'body2d', 'svg', f), 'utf8').matchAll(/data-zone-id="([a-z_]+)"/g)].map((m) => m[1]))].sort();
    (views[g] ||= {})[v] = ids;
  }
  fs.writeFileSync(path.join(APP, 'src', 'lib', 'body3d', 'zone-views.json'), JSON.stringify(views, null, 1));
  console.log('   zone-views.json written');
}
// 2D callouts module + its stylesheet (Brand Designer, R-2D-02): markers, leader callouts, crosshair (one copy of the logic)
copy(path.join(SITE, 'design', 'body2d', 'lib', 'body2d-callouts.mjs'), path.join(APP, 'src', 'lib', 'body2d', 'body2d-callouts.mjs'));
copy(path.join(SITE, 'design', 'body2d', 'body2d.css'), path.join(APP, 'src', 'styles', 'body2d.css'));
copy(path.join(SITE, 'design', 'brand-kit', 'fonts', 'Manrope-subset.woff2'), path.join(APP, 'src', 'fonts', 'Manrope.woff2'));
copy(path.join(SITE, 'design', 'brand-kit', 'fonts', 'OFL.txt'), path.join(APP, 'src', 'fonts', 'OFL.txt'));
// 4) favicons + web manifests (brand kit head-snippet.html: site root paths)
for (const f of ['favicon.svg', 'favicon-32.png', 'favicon-16.png', 'favicon.ico', 'apple-touch-icon.png', 'icon-192.png', 'icon-512.png', 'icon-maskable-512.png', 'site.webmanifest', 'site.ru.webmanifest'])
  copy(path.join(SITE, 'design', 'brand-kit', 'favicon', f), path.join(APP, 'public', f));
// 5) photos (site/visuals/final, passed R-VIS-01) → public/photos/{set}/{id}-{w}.{avif|webp}; manifest → src/lib/visuals.
//    AVIF + WebP at every width; JPEG only at 640 as the last-resort <img src> (lead, R-APP-02 N-08, ТЗ §11: old iOS) — the
//    copied manifest lists exactly the published files (formats + jpgWidths), so components never point at a missing file.
{
  const FINAL = path.join(SITE, 'visuals', 'final');
  if (fs.existsSync(path.join(FINAL, 'manifest.json'))) {
    const man = JSON.parse(fs.readFileSync(path.join(FINAL, 'manifest.json'), 'utf8'));
    const FORMATS = ['avif', 'webp'];
    const JPG_WIDTHS = [640];
    const outDir = path.join(APP, 'public', 'photos');
    fs.rmSync(outDir, { recursive: true, force: true }); // no stale photos
    let n = 0;
    for (const it of man.items) for (const w of man.widths) for (const f of [...FORMATS, ...(JPG_WIDTHS.includes(w) ? ['jpg'] : [])]) {
      const src = path.join(FINAL, it.set, `${it.id}-${w}.${f}`);
      if (!fs.existsSync(src)) { console.error('visuals: missing', rel(src)); process.exit(1); }
      fs.mkdirSync(path.join(outDir, it.set), { recursive: true });
      fs.copyFileSync(src, path.join(outDir, it.set, `${it.id}-${w}.${f}`)); n++;
    }
    const { note: _note, _source: _src, ...rest } = man; // the authors' note stays in the source manifest (В-5)
    const published = {
      ...rest, formats: [...FORMATS, 'jpg'], jpgWidths: JPG_WIDTHS, path: '/photos/{set}/{id}-{w}.{fmt}', fallback: 'jpg',
      items: man.items.map((it) => ({ ...it, files: Object.fromEntries(Object.entries(it.files).filter(([k]) => FORMATS.some((f) => k.endsWith(`.${f}`)) || JPG_WIDTHS.some((w) => k === `${w}.jpg`))) })),
    };
    fs.mkdirSync(path.join(APP, 'src', 'lib', 'visuals'), { recursive: true });
    fs.writeFileSync(path.join(APP, 'src', 'lib', 'visuals', 'manifest.json'), JSON.stringify(published, null, 1));
    console.log(`   photos: ${n} files (${man.items.length} items × ${man.widths.length} widths × ${FORMATS.join('/')} + jpg ${JPG_WIDTHS.join('/')}) + src/lib/visuals/manifest.json`);
  }
}

// 6) brand kit for the header / footer (Web Art Director) and OG images (lib/seo.ts)
{
  const BK = path.join(SITE, 'design', 'brand-kit');
  for (const f of ['bm-lockup-horizontal-color', 'bm-lockup-compact-nano-color', 'bm-footer-giant-wide-on-dark', 'bm-footer-giant-stacked-on-dark', 'bm-footer-giant-stacked-centered-on-dark' /* phones, Brand Designer */, 'bm-full-mono-dark' /* tone-on-tone mark of the photo placeholders (mask) */]) {
    const src = path.join(BK, 'svg', `${f}.svg`);
    if (fs.existsSync(src)) copy(src, path.join(APP, 'public', 'brand', `${f}.svg`));
  }
  brandPlates(path.join(APP, 'public', 'brand')); // header copies with a light plate (D-06), scripts/brand-plate.mjs
  for (const l of ['ru', 'en']) {
    const src = path.join(BK, 'og', `og-template-${l}.png`);
    if (fs.existsSync(src)) copy(src, path.join(APP, 'public', 'og', `og-template-${l}.png`));
    // the ad landings' own cards (RC-9, C-1: the site card names services the landings must not) — one per version and language
    for (const v of ['a', 'b']) {
      const lp = path.join(BK, 'og', `og-lp-${v}-${l}.png`);
      if (fs.existsSync(lp)) copy(lp, path.join(APP, 'public', 'og', `og-lp-${v}-${l}.png`));
      else console.warn(`   ! brand kit: og/og-lp-${v}-${l}.png not found — the committed copy stays`);
    }
  }
}

console.log('sync-assets: done');
